-- fdh-c-check: ip row count of PHDB
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns adp_phdb
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT SUM(nd.icode IS NOT NULL AND COALESCE(inc.drg_chrgitem_id, 0) NOT IN (3,4)) AS adp_phdb, SUM(d.icode IS NOT NULL AND pt.hn IS NOT NULL AND inc.drg_chrgitem_id IN (3,4)) AS dru FROM p JOIN ipt a ON a.dchdate BETWEEN p.s AND p.e JOIN opitemrece op FORCE INDEX (ix_an) ON op.an = a.an LEFT JOIN income inc ON inc.income = op.income LEFT JOIN nondrugitems nd ON nd.icode = op.icode LEFT JOIN drugitems d ON d.icode = op.icode LEFT JOIN patient pt ON pt.hn = op.hn;
